INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(16001, 'Proverbs 21:5', 'Proverbs', 21, 5, '&nbsp;د محنتى انسان منصوبې د آبادۍ باعث ګرځى، خو په يقين سره جلد بازى انسان د غربت سره مخ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16002, 'Proverbs 21:6', 'Proverbs', 21, 6, '&nbsp;کوم مال دولت چې په دروغژنه ژبه وګټلے شى نو دا د ختمېدونکى دوند او وژونکى دام په شان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16003, 'Proverbs 21:7', 'Proverbs', 21, 7, '&nbsp;بدکاران به د خپل ظلم زياتى په وجه جارُو شى، ځکه چې هغوئ د هر هغه کار نه اِنکار کوى کوم چې صحيح وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16004, 'Proverbs 21:8', 'Proverbs', 21, 8, '&nbsp;د ګناه ګار لاره کږه وږه وى، خو د پاکانو لاره نېغه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16005, 'Proverbs 21:9', 'Proverbs', 21, 9, '&nbsp;دا بهتره ده چې د کوټې دپاسه په يو ګوټ کښې ځانله ژوند کوى نه چې په کور کښې د ژبه ورې ښځې سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16006, 'Proverbs 21:10', 'Proverbs', 21, 10, '&nbsp;بدکاره انسان د بدۍ خواهشمند وى، د هغۀ ګاونډيان هم هيڅ قِسمه رحم د هغۀ نه نۀ وينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16007, 'Proverbs 21:11', 'Proverbs', 21, 11, '&nbsp;کله چې يو مسخره کوونکى ته سزا ورکړے شى، نو ساده هم ترې نه عقل زده کړى، خو کله چې د هوښيار لارښودنه وشى، نو هغه ترې نه نور عِلم حاصلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16008, 'Proverbs 21:12', 'Proverbs', 21, 12, '&nbsp;صادقه خُدائ هغه هر څۀ وينى کوم چې د بدکاره په کور کښې کيږى، او په بدکاره به هغه تباهى راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16009, 'Proverbs 21:13', 'Proverbs', 21, 13, '&nbsp;کۀ يو سړے د غريب ژړا فرياد ته خپل غوږونه بند کړى، نو د هغۀ خپله ژړا فرياد به څوک نۀ اورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16010, 'Proverbs 21:14', 'Proverbs', 21, 14, '&nbsp;په پرده کښې تحفه ورکول غصه نرموى، په پټه رشوت ورکول انسان د غټ قهر نه ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16011, 'Proverbs 21:15', 'Proverbs', 21, 15, '&nbsp;هرکله چې اِنصاف وشى، نو په دې صادق خوشحاليږى، خو بدکاره ترې نه يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16012, 'Proverbs 21:16', 'Proverbs', 21, 16, '&nbsp;څوک چې د حِکمت د لارې نه بې‌لارې شى، نو هغه به د مړو په ډله کښې شمار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16013, 'Proverbs 21:17', 'Proverbs', 21, 17, '&nbsp;څوک چې د عياشۍ سره مينه کوى نو هغه به غريب شى، څوک چې د ميو او غوړو زېړو سره مينه کوى هغه به مالداره نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16014, 'Proverbs 21:18', 'Proverbs', 21, 18, '&nbsp;د صادقانو په ځائ بدکاران سزاوار شو، او د هغوئ په ځائ د نافرمانو فديه ورکړے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16015, 'Proverbs 21:19', 'Proverbs', 21, 19, '&nbsp;د جنګ ببره او سرتېزه ښځې سره د اوسېدو نه په صحرا کښې اوسېدل ښۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16016, 'Proverbs 21:20', 'Proverbs', 21, 20, '&nbsp;د هوښيارانو په کور کښې ښۀ خوراکونه ډېر تير وى، خو کم عقل چې څۀ ګټى هغه څټى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16017, 'Proverbs 21:21', 'Proverbs', 21, 21, '&nbsp;څوک چې صداقت او شفقت پسې ګرځى، هغه به ژوندون، آبادى او عزت پېدا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16018, 'Proverbs 21:22', 'Proverbs', 21, 22, '&nbsp;يو هوښيار انسان په يو طاقتور ښار حمله کولے شى، او هغه قوى دېوالونه راغورزولے شى په کومو چې هغوئ ملا تړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16019, 'Proverbs 21:23', 'Proverbs', 21, 23, '&nbsp;څوک چې خپله خولۀ او ژبه په قابو کښې ساتى، خپل ځان د مصيبت نه خلاصوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16020, 'Proverbs 21:24', 'Proverbs', 21, 24, '&nbsp;مغروره او ځان ښولے سړے چې مسخره کوونکے يې نوم دے، هغه هر کار د تکبر سره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16021, 'Proverbs 21:25', 'Proverbs', 21, 25, '&nbsp;د ناراسته خواهش هغه د مرګ طرف ته بوځى، ځکه چې هغه د کار کولو نه اِنکار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16022, 'Proverbs 21:26', 'Proverbs', 21, 26, '&nbsp;ټوله ورځ دے د نورو خواهش کوى، خو نېکان تل په سخاوت کښې لګيا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16023, 'Proverbs 21:27', 'Proverbs', 21, 27, '&nbsp;د بدکاره د قربانۍ نه مالِک خُدائ کرکه کوى، نو د هغې نه به نور څومره کرکه کوى کومه چې په بدنېتۍ سره کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16024, 'Proverbs 21:28', 'Proverbs', 21, 28, '&nbsp;دروغژن ګواه به تباه شى، او څوک چې رښتيا وائى هغه به د تل دپاره خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16025, 'Proverbs 21:29', 'Proverbs', 21, 29, '&nbsp;يو بدکاره انسان خپل ځان تکړه ښائى خو صادق انسان په خپلو لارو باندې سوچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16026, 'Proverbs 21:30', 'Proverbs', 21, 30, '&nbsp;هيڅ قسمه حِکمت، عقل او منصوبه نشته چې د مالِک خُدائ خلاف کاميابه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16027, 'Proverbs 21:31', 'Proverbs', 21, 31, '&nbsp;آس د جنګ د ورځې دپاره تيارولے شى، خو کاميابى د مالِک خُدائ په لاس کښې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16028, 'Proverbs 22:1', 'Proverbs', 22, 1, '&nbsp;نېک نامى د ډېر مال دولت نه غوره ده، عزت د سرو او سپينو زرو نه بهتر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16029, 'Proverbs 22:2', 'Proverbs', 22, 2, '&nbsp;مالداره او غريب دواړه يو شان دى، مالِک خُدائ د دواړو خالق دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16030, 'Proverbs 22:3', 'Proverbs', 22, 3, '&nbsp;هوښيار سړے چې خطره ووينى نو خپل ځان ترېنه ساتى، خو ساده سړے پرې وردانګى او بيا مصيبت کښې راګېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16031, 'Proverbs 22:4', 'Proverbs', 22, 4, '&nbsp;عاجزى او د مالِک خُدائ نه يرېدل، انسان ته مال دولت، عزت او ژوند ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16032, 'Proverbs 22:5', 'Proverbs', 22, 5, '&nbsp;د بدکارانو په لار کښې ازغى او دامونه وى، خو په چا چې خپل ځان ګران وى نو هغه د دوئ نه ځان بچ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16033, 'Proverbs 22:6', 'Proverbs', 22, 6, '&nbsp;ماشوم په صحيح لار روان کړه، دے چې لوئ هم شى د هغې نه به وانۀ وړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16034, 'Proverbs 22:7', 'Proverbs', 22, 7, '&nbsp;مالداره په غريبانانو باندې حکومت کوى، او قرض اخستونکے د قرض ورکونکى غلام وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16035, 'Proverbs 22:8', 'Proverbs', 22, 8, '&nbsp;کۀ څوک نا اِنصافى کَرى نو مصيبت به وريبى، او د هغۀ د کبر کاسه به نسکوره شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16036, 'Proverbs 22:9', 'Proverbs', 22, 9, '&nbsp;بختور دى هغوئ څوک چې سخاوت کوى، ځکه چې هغوئ غريبانان مړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16037, 'Proverbs 22:10', 'Proverbs', 22, 10, '&nbsp;پېغور کوونکے کس وشړه، دې سره به جنګ جګړې ختمې شى، بحث مباحثه او سپکاوے هم ورسره ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16038, 'Proverbs 22:11', 'Proverbs', 22, 11, '&nbsp;څوک چې په زړۀ صفا وى او خوږې خبرې کوى، نو بادشاه به هم د هغۀ دوست شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16039, 'Proverbs 22:12', 'Proverbs', 22, 12, '&nbsp;د مالِک خُدائ نظر په عالمانو باندې وى، خو هغه د بې‌وفا خلقو منصوبې ورانوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16040, 'Proverbs 22:13', 'Proverbs', 22, 13, '&nbsp;ناراسته وائى، ”بهر زمرے دے. کۀ چرې بهر ووځم نو هغه به مې په لار کښې ووژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16041, 'Proverbs 22:14', 'Proverbs', 22, 14, '&nbsp;د زناکارې ښځې خولۀ د ژورې کندې په شان ده، چا ته چې مالِک خُدائ په قهر شوے وى هغه به په کښې ورغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16042, 'Proverbs 22:15', 'Proverbs', 22, 15, '&nbsp;د ماشومانو زړۀ د کم عقلتوب نه ډک وى، خو د وهلو چوکه د هغوئ نه دا عادت وکاږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16043, 'Proverbs 22:16', 'Proverbs', 22, 16, '&nbsp;څوک چې په غريبانانو باندې ظلم کوى د دې دپاره چې مالداره شى او هغه څوک چې اميرانو ته تحفې ورکوى نو دا دواړه به غريب شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16044, 'Proverbs 22:17', 'Proverbs', 22, 17, '&nbsp;د هوښيارانو خبرو ته غوږ کېږده او هغې ته پام وکړه او زما تعليم د زړۀ نه قبول کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16045, 'Proverbs 22:18', 'Proverbs', 22, 18, '&nbsp;نو دا به تا خوشحاله کړى کۀ تۀ دا په خپل زړۀ کښې ياد ساتې او دا په خپلو شونډو هر وخت يادوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16046, 'Proverbs 22:19', 'Proverbs', 22, 19, '&nbsp;زۀ نن تا ته تعليم درکوم دا چې ستا ايمان په مالِک خُدائ باندې پېدا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16047, 'Proverbs 22:20', 'Proverbs', 22, 20, '&nbsp;ما ستا دپاره دېرش خبرې ليکلې دى په کومو کښې چې عِلم، او نصيحت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16048, 'Proverbs 22:21', 'Proverbs', 22, 21, '&nbsp;او زۀ به تا ته رښتيا او د اعتماد وړ خبرې دروښايم، ترڅو چې قابل اعتماد جواب ورکولے شې هغه چا ته چا چې تۀ رالېږلے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16049, 'Proverbs 22:22', 'Proverbs', 22, 22, '&nbsp;د غريبانانو د غريبۍ نه غلطه فائده مۀ اخله، او په عدالت کښې د حاجتمندو حق مۀ خوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16050, 'Proverbs 22:23', 'Proverbs', 22, 23, '&nbsp;ځکه چې مالِک خُدائ به په خپل لاس کښې د دوئ مقدمه واخلى او هغوئ به لوټ کړى، چا چې دوئ لوټ کړى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16051, 'Proverbs 22:24', 'Proverbs', 22, 24, '&nbsp;د غصه ناکو سره دوستانه مۀ کوه، او د قهرژنو سره ناسته مۀ کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16052, 'Proverbs 22:25', 'Proverbs', 22, 25, '&nbsp;هسې نه چې تۀ د هغوئ عادتونه زده کړې او خپل ځان په مصيبت کښې راګېر کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16053, 'Proverbs 22:26', 'Proverbs', 22, 26, '&nbsp;د چا په ځائ د ضمانت لاس مۀ ورکوه او مۀ د قرض ذمه وارى اخله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16054, 'Proverbs 22:27', 'Proverbs', 22, 27, '&nbsp;کۀ تۀ هغوئ له دا قرض ورنۀ کړے شې هغوئ به راشى او تۀ چې په کوم کټ اودۀ کېږې نو هغه به درنه يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16055, 'Proverbs 22:28', 'Proverbs', 22, 28, '&nbsp;په زمکه کښې هغه د حد بندۍ وړومبے کاڼے مۀ بې‌ځايه کوه کوم چې ستا پلار نيکۀ اېښے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16056, 'Proverbs 22:29', 'Proverbs', 22, 29, '&nbsp;تۀ داسې يو کس وينې، څوک چې په خپل کار کښې ماهر وى؟ هغه به د عامو خلقو خِدمت نۀ کوى، خو د بادشاهانو خِدمت به کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16057, 'Proverbs 23:1', 'Proverbs', 23, 1, '&nbsp;کله چې تۀ يو حاکِم سره روټۍ خوړلو ته کښېنې، نو دا په ذهن کښې راوله چې ستا وړاندې څۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16058, 'Proverbs 23:2', 'Proverbs', 23, 2, '&nbsp;په خپله مرۍ چاړۀ کېږده کۀ تۀ زيات خوړونکے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16059, 'Proverbs 23:3', 'Proverbs', 23, 3, '&nbsp;د هغۀ د مزېدار خوراک ډېر خواهش مۀ کوه، ځکه چې دا دوکه ورکوونکے خوراک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16060, 'Proverbs 23:4', 'Proverbs', 23, 4, '&nbsp;خپل ځان په مالداره کولو مۀ ستړے کوه. دومره هوښيار شه چې د داسې کولو نه ځان ساتې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16061, 'Proverbs 23:5', 'Proverbs', 23, 5, '&nbsp;ستا دولت به د سترګو په رپ کښې فنا شى، او خپلې وزرې به پرانيزى او د باز په شان به آسمان ته والوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16062, 'Proverbs 23:6', 'Proverbs', 23, 6, '&nbsp;د يو شوم سړى روټۍ مۀ خوره او د هغۀ د مزيدارو خوراکونو ارمان مۀ کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16063, 'Proverbs 23:7', 'Proverbs', 23, 7, '&nbsp;هغه داسې سړے دے چې همېشه د خرچ سوچ کوى، هغه تاسو ته وائى چې، ”راشئ ما سره وخورئ وڅښئ.“ خو هغه د زړۀ نه دا خبره نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16064, 'Proverbs 23:8', 'Proverbs', 23, 8, '&nbsp;ځکه چې تاسو څۀ خوړلى وى هغه به په پوزه باقۍ کړئ او ستاسو ټولې ښُکلې خبرې به بې‌فائدې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16065, 'Proverbs 23:9', 'Proverbs', 23, 9, '&nbsp;يو کم عقل ته خبرې مۀ کوه، هغه به ستا د حِکمت خبرې سپکې ګڼى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16066, 'Proverbs 23:10', 'Proverbs', 23, 10, '&nbsp;په زمکه کښې هغه د حد بندۍ وړومبے کاڼے مۀ بې‌ځايه کوه او مۀ د يتيمانو په زمکه باندې قبضه کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16067, 'Proverbs 23:11', 'Proverbs', 23, 11, '&nbsp;ځکه چې د هغوئ بچ کوونکے زورَور دے او هغه به ستاسو خِلاف د هغوئ د مقدمې طرفدارے وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16068, 'Proverbs 23:12', 'Proverbs', 23, 12, '&nbsp;خپل زړۀ تربيت ته حواله کړه او خپل غوږونه د حِکمت خبرو ته نيسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16069, 'Proverbs 23:13', 'Proverbs', 23, 13, '&nbsp;د خپل اولاد تربيت مۀ پرېږده. کۀ تۀ هغوئ ته په چوکه سزا ورکړې نو هغوئ به د دې نه مړۀ نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16070, 'Proverbs 23:14', 'Proverbs', 23, 14, '&nbsp;هغۀ ته په چوکه سزا ورکړئ او هغه به د عالمِ ارواح نه بچ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16071, 'Proverbs 23:15', 'Proverbs', 23, 15, '&nbsp;زما زويه، کۀ تۀ عقلمند يې، نو زما زړۀ به خوشحاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16072, 'Proverbs 23:16', 'Proverbs', 23, 16, '&nbsp;دننه روح به په ما کښې په ټوپونو شى کله چې تۀ رښتيا خبرې کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16073, 'Proverbs 23:17', 'Proverbs', 23, 17, '&nbsp;خپل زړۀ مۀ پرېږده چې د ګناهګارو سره حسد وکړى، خو د مالِک خُدائ نه هر وخت په يره کښې اوسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16074, 'Proverbs 23:18', 'Proverbs', 23, 18, '&nbsp;په يقين سره ستا دپاره په راتلونکى وخت کښې اُميد شته دے او ستا اُميد به نۀ ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16075, 'Proverbs 23:19', 'Proverbs', 23, 19, '&nbsp;زما زويه، ما ته غوږ ونيسه، هوښيار اوسه، او خپل زړۀ په صحيح لار باندې قائم وساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16076, 'Proverbs 23:20', 'Proverbs', 23, 20, '&nbsp;د شرابيانو سره ناسته پاسته مۀ کوه، او د خېټورو سره مۀ ګرځېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16077, 'Proverbs 23:21', 'Proverbs', 23, 21, '&nbsp;ځکه چې شرابيان او خيټور به غريبانان شى. او ډېر خوب به هغوئ ته شلېدلې جامې ورواغوندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16078, 'Proverbs 23:22', 'Proverbs', 23, 22, '&nbsp;خپل پلار ته غوږ نيسه، چا چې تا له ژوند درکړے دے، او د خپلې مور بې‌عزتى مۀ کوه کله چې هغه بوډۍ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16079, 'Proverbs 23:23', 'Proverbs', 23, 23, '&nbsp;حقيقت حاصل کړه او دا مۀ خرڅوه، او حِکمت، تربيت او پوهه حاصله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16080, 'Proverbs 23:24', 'Proverbs', 23, 24, '&nbsp;د صادق سړى پلار ډېر خوشحاله وى، هغه څوک چې هوښيار زوئ لرى په هغۀ باندې فخر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16081, 'Proverbs 23:25', 'Proverbs', 23, 25, '&nbsp;ستا مور او پلار دې خوشحالى وکړى، او هغه دې خوشحالى وکړى چا چې تۀ زيږولے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16082, 'Proverbs 23:26', 'Proverbs', 23, 26, '&nbsp;زما زويه، خپل زړۀ ما ته راکړه او ما ته وګوره او په خوشحالۍ سره زما په طريقو باندې عمل وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16083, 'Proverbs 23:27', 'Proverbs', 23, 27, '&nbsp;ځکه چې کنجره د ژورې کندې په شان وى او زناکاره د تنګ کوهى په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16084, 'Proverbs 23:28', 'Proverbs', 23, 28, '&nbsp;هغوئ د ډاکوانو په شان په انتظار کښې ناستې وى او بې‌وفا سړى زياتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16085, 'Proverbs 23:29', 'Proverbs', 23, 29, '&nbsp;څوک دى چې وير کوى؟ څوک دى چې غمژن دى؟ څوک دى چې جګړه کوى؟ څوک دى چې شکايت کوى؟ څوک دى چې هسې زخمونه لرى؟ څوک دى چې سرې سترګې لرى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16086, 'Proverbs 23:30', 'Proverbs', 23, 30, '&nbsp;دا هغوئ دى څوک چې په مےخانو کښې وخت تېروى، او د رنګارنګ ميو پيالۍ څښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16087, 'Proverbs 23:31', 'Proverbs', 23, 31, '&nbsp;ميو ته مۀ ګوره کله چې دا سرۀ وى او کله چې په پياله کښې شُغلې وهى او په آسانه سره تېريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16088, 'Proverbs 23:32', 'Proverbs', 23, 32, '&nbsp;په آخر کښې دا لکه د مار چيچل کوى او لکه د منګور په شان زهريله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16089, 'Proverbs 23:33', 'Proverbs', 23, 33, '&nbsp;ستا سترګې به عجيبه او رنګارنګ څيزونه ګورى، او ستا ذهن به د ګډوډو څيزونو تصور کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16090, 'Proverbs 23:34', 'Proverbs', 23, 34, '&nbsp;تۀ به په خيال کښې د هغه چا په شان يې څوک چې د سمندر دپاسه اودۀ وى، او د چپو دپاسه پروت ټالۍ وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16091, 'Proverbs 23:35', 'Proverbs', 23, 35, '&nbsp;نو تۀ خپل ځان ته وائې، ”هغوئ زۀ ووهلم، خو زۀ خوږ نۀ شوم، هغوئ زۀ وټکولم، خو ما ته پته ونۀ لګېدله. کله چې زۀ راويښ شم نو زۀ به د څښلو دپاره نور شراب هم پېدا کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16092, 'Proverbs 24:1', 'Proverbs', 24, 1, '&nbsp;د بدکارانو سره حسد مۀ کوه او د هغوئ د دوستانې آرزو مۀ کوه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16093, 'Proverbs 24:2', 'Proverbs', 24, 2, '&nbsp;ځکه چې هغوئ په زړۀ کښې د شر او فساد منصوبې جوړوى، او د هغوئ خبرې تل مصيبت جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16094, 'Proverbs 24:3', 'Proverbs', 24, 3, '&nbsp;يو کور په حِکمت سره جوړيږى، او د پوهې په وجه هغه قائم پاتې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16095, 'Proverbs 24:4', 'Proverbs', 24, 4, '&nbsp;د عِلم په واسطې سره د هغۀ کوټې د نايابه او قيمتى خزانو سره ښائسته کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16096, 'Proverbs 24:5', 'Proverbs', 24, 5, '&nbsp;يو هوښيار انسان لوئ طاقت لرى، او د عالم قوت ورځ په ورځ نور هم زياتيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16097, 'Proverbs 24:6', 'Proverbs', 24, 6, '&nbsp;د جنګ کولو دپاره د ښۀ هدايت ضرورت وى، او د ګڼو مشوره ورکوونکو سره کاميابى يقينى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16098, 'Proverbs 24:7', 'Proverbs', 24, 7, '&nbsp;کم عقل هوښيارتيا نۀ شى حاصلولے، ځکه په جرګه کښې د هغۀ خولۀ بنده وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16099, 'Proverbs 24:8', 'Proverbs', 24, 8, '&nbsp;څوک چې بدې منصوبې جوړوى، نو هغه به په دوکه مار مشهور شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16100, 'Proverbs 24:9', 'Proverbs', 24, 9, '&nbsp;د کم عقلو منصوبې د ګناه نه ډکې وى، او خلق د مسخره کوونکى نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');